              sku: line.sku,
              delta: line.quantity,
            }
          );
          await tx.execute(
            `UPDATE StockItem FILTER .sku = <str>$sku
             SET { reserved := .reserved - <int64>$qty }`,
            { sku: line.sku, qty: line.quantity }
          );
        }

        released.push(res.id);
      }

      released.sort();
      return { released };
    });
  } finally {
    await client.close();
  }
}

export async function snapshot(): Promise<Snapshot> {
  const client = getClient();
  try {
    const items = await client.query<{
      sku: string;
      stock: number;
      reserved: number;
    }>(`SELECT StockItem { sku, stock, reserved } ORDER BY .sku`);

    const reservationsRaw = await client.query<{
      id: string;
      key: string;
      state: string;
      lines: { sku: string; quantity: number }[];
    }>(
      `SELECT Reservation {
        id,
        key,
        state,
        lines: {
          sku := .item.sku,
          quantity
        } ORDER BY .item.sku
      } ORDER BY .id`
    );

    const ledgerRaw = await client.query<{
      reservationId: string;
      sku: string;
      kind: string;
      delta: number;
    }>(
      `SELECT LedgerEntry {
        reservationId := .reservation.id,
        sku := .item.sku,
        kind,
        delta
      }`
    );

    return {
      items: items.map((i) => ({
        sku: i.sku,
        stock: Number(i.stock),
        reserved: Number(i.reserved),
        available: Number(i.stock) - Number(i.reserved),
      })),
      reservations: reservationsRaw.map((r) => ({
        reservationId: r.id,
        idempotencyKey: r.key,
        state: r.state as "active" | "released",
        lines: r.lines.map((l) => ({
          sku: l.sku,
          quantity: Number(l.quantity),
        })),
      })),
      ledger: ledgerRaw.map((e) => ({
        reservationId: e.reservationId,
        sku: e.sku,
        kind: e.kind as "reserve" | "release",
        delta: Number(e.delta),
      })),
    };
  } finally {
    await client.close();
  }
}

export function getRetryAttempts(): number {
  return RETRY_ATTEMPTS;
}

import {
  resetCatalog,
  reserve,
  reserveMany,
  release,
  expireDue,
  snapshot,
  getRetryAttempts,
} from "./reservations";

async function main(): Promise<void> {
  let input = "";
  process.stdin.setEncoding("utf-8");

  for await (const chunk of process.stdin) {
    input += chunk;
  }

  let command: any;
  try {
    command = JSON.parse(input);
  } catch {
    process.stderr.write("invalid json\n");
    process.exit(1);
  }

  try {
    let result: any;

    switch (command.op) {
      case "reset": {
        result = await resetCatalog(command.items);
        break;
      }
      case "reserve": {
        result = await reserve(command.request);
        break;
      }
      case "reserveMany": {
        result = await reserveMany(command.requests);
        break;
      }
      case "release": {
        result = await release(command.reservationId);
        break;
      }
      case "expire": {
        result = await expireDue(command.now);
        break;
      }
      case "snapshot": {
        result = await snapshot();
        break;
      }
      case "retryAttempts": {
        result = { attempts: getRetryAttempts() };
        break;
      }
      default: {
        process.stderr.write(`unknown op: ${command.op}\n`);
        process.exit(1);
      }
    }

    process.stdout.write(JSON.stringify(result) + "\n");
    process.exit(0);
  } catch (err: any) {
    process.stderr.write(`error: ${err?.message ?? String(err)}\n`);
    process.exit(1);
  }
}

main();

