        await tx.execute(
          `INSERT LedgerEntry {
            reservation := (SELECT Reservation FILTER .id = <uuid>$resId),
            item := (SELECT StockItem FILTER .sku = <str>$sku),
            delta := <int64>$delta,
            kind := 'reserve'
          }`,
          {
